<script>
(function(){
  "use strict";
  var TAU = Math.PI*2;

  /* ---------- procedural face textures (used as albedo + bump maps) ---------- */
  function circText(g, str, cx, cy, r, centerAng, fontPx, up){
    g.font = "600 "+fontPx+"px Georgia, serif";
    g.textAlign="center"; g.textBaseline="middle";
    var chars = str.split("");
    var widths = chars.map(function(c){ return g.measureText(c).width; });
    var total = widths.reduce(function(a,b){return a+b;},0);
    var totalAng = total/r;
    var ang = up ? (centerAng - totalAng/2) : (centerAng + totalAng/2);
    for(var k=0;k<chars.length;k++){
      var w = widths[k];
      var a = up ? (ang + (w/2)/r) : (ang - (w/2)/r);
      var x = cx + Math.cos(a)*r, y = cy + Math.sin(a)*r;
      g.save(); g.translate(x,y);
      g.rotate(up ? (a+Math.PI/2) : (a-Math.PI/2));
      g.fillText(chars[k],0,0);
      g.restore();
      ang += up ? (w/r) : -(w/r);
    }
  }
  function star(g, cx, cy, rO, rI, points){
    g.beginPath();
    for(var i=0;i<points*2;i++){
      var rr = (i%2===0)?rO:rI;
      var a = -Math.PI/2 + i*Math.PI/points;
      var x=cx+Math.cos(a)*rr, y=cy+Math.sin(a)*rr;
      if(i===0) g.moveTo(x,y); else g.lineTo(x,y);
    }
    g.closePath(); g.fill();
  }

  function buildFace(kind){
    var N=256;
    var c=document.createElement("canvas"); c.width=c.height=N;
    var g=c.getContext("2d");
    g.fillStyle="#808080"; g.fillRect(0,0,N,N); // neutral flat field
    var cx=N/2, cy=N/2;
    g.lineJoin="round"; g.lineCap="round";
    g.strokeStyle="#f2f2f2"; g.fillStyle="#f4f4f4";

    // rings
    g.lineWidth=N*0.014;
    g.beginPath(); g.arc(cx,cy,N*0.462,0,TAU); g.stroke();
    g.lineWidth=N*0.010;
    g.beginPath(); g.arc(cx,cy,N*(kind==="front"?0.305:0.322),0,TAU); g.stroke();

    // tick ring
    g.lineWidth=N*0.006;
    for(var i=0;i<72;i++){
      var a=i*TAU/72;
      var r1=N*0.428, r2=N*0.446;
      g.beginPath();
      g.moveTo(cx+Math.cos(a)*r1, cy+Math.sin(a)*r1);
      g.lineTo(cx+Math.cos(a)*r2, cy+Math.sin(a)*r2);
      g.stroke();
    }

    if(kind==="front"){
      circText(g,"✦ WASTEDTOKEN MINT ✦", cx,cy, N*0.388, -Math.PI/2, N*0.052, true);
      circText(g,"COLLECTIBLE CHALLENGE COIN", cx,cy, N*0.388,  Math.PI/2, N*0.044, false);
      // central emblem: raised star + monogram
      g.fillStyle="#f6f6f6";
      star(g, cx, cy-N*0.01, N*0.185, N*0.078, 5);
      g.fillStyle="#2a2a2a";
      star(g, cx, cy-N*0.01, N*0.088, N*0.036, 5);
      g.fillStyle="#f6f6f6";
      g.font="700 "+(N*0.088)+"px Georgia, serif";
      g.textAlign="center"; g.textBaseline="middle";
      g.fillText("WT", cx, cy-N*0.008);
      g.font="600 "+(N*0.05)+"px Georgia, serif";
      g.fillText("EST · MMXXI", cx, cy+N*0.22);
    } else {
      circText(g,"WASTEDTOKEN MINT", cx,cy, N*0.405, -Math.PI/2, N*0.056, true);
      circText(g,"· ONE PHYSICAL TOKEN ·", cx,cy, N*0.405, Math.PI/2, N*0.046, false);
      g.fillStyle="#f6f6f6";
      g.textAlign="center"; g.textBaseline="middle";
      g.font="700 "+(N*0.155)+"px Georgia, serif";
      g.fillText("10,000", cx, cy-N*0.03);
      g.font="700 "+(N*0.072)+"px Georgia, serif";
      g.fillText("TOKENS", cx, cy+N*0.11);
      // flanking stars
      g.fillStyle="#f0f0f0";
      star(g, cx-N*0.235, cy-N*0.02, N*0.028, N*0.012, 5);
      star(g, cx+N*0.235, cy-N*0.02, N*0.028, N*0.012, 5);
    }

    var img=g.getImageData(0,0,N,N).data;
    var lum=new Float32Array(N*N), gx=new Float32Array(N*N), gy=new Float32Array(N*N);
    for(var p=0;p<N*N;p++){
      lum[p]=(img[p*4]+img[p*4+1]+img[p*4+2])/(3*255);
    }
    for(var y=1;y<N-1;y++)for(var x=1;x<N-1;x++){
      var idx=y*N+x;
      gx[idx]=lum[idx+1]-lum[idx-1];
      gy[idx]=lum[idx+N]-lum[idx-N];
    }
    return {N:N,lum:lum,gx:gx,gy:gy};
  }

  var texFront=buildFace("front");
  var texBack =buildFace("back");

  /* ---------- metals ---------- */
  var METALS={
    gold:    {base:[1.00,0.80,0.36], spec:[1.00,0.92,0.70], shin:78, amb:0.17},
    bronze:  {base:[0.82,0.52,0.30], spec:[1.00,0.82,0.55], shin:58, amb:0.16},
    silver:  {base:[0.85,0.87,0.93], spec:[1.00,1.00,1.00], shin:92, amb:0.19},
    obsidian:{base:[0.14,0.15,0.20], spec:[0.72,0.80,0.98], shin:120,amb:0.10}
  };

  /* ---------- geometry / constants ---------- */
  var R=1, H=0.11, DOME=0.30, BUMP=0.85, REEDAMP=0.55, NR=100, FIT=0.94;
  // light
  (function(){var Lx=-0.35,Ly=0.52,Lz=0.80,ln=Math.hypot(Lx,Ly,Lz);
    window.__L=[Lx/ln,Ly/ln,Lz/ln];})();
  var L=window.__L;
  var Hx=L[0], Hy=L[1], Hz=L[2]+1;
  (function(){var hn=Math.hypot(Hx,Hy,Hz);Hx/=hn;Hy/=hn;Hz/=hn;})();

  function texAt(tex,su,sv,out){
    var N=tex.N;
    var fx=(0.5+su*FIT*0.5)*N;
    var fy=(0.5-sv*FIT*0.5)*N;
    var xi=fx|0, yi=fy|0;
    if(xi<1)xi=1; if(xi>N-2)xi=N-2; if(yi<1)yi=1; if(yi>N-2)yi=N-2;
    var idx=yi*N+xi;
    out[0]=tex.lum[idx]; out[1]=tex.gx[idx]; out[2]=tex.gy[idx];
  }

  var tmp=[0,0,0];

  function renderInto(data, res, yaw, pitch, metal){
    var ca=Math.cos(yaw), sa=Math.sin(yaw), cp=Math.cos(pitch), sp=Math.sin(pitch);
    // object->world rotation M
    var m00=ca, m01=0, m02=sa;
    var m10=sp*sa, m11=cp, m12=-sp*ca;
    var m20=-cp*sa, m21=sp, m22=cp*ca;
    // ray dir (object space), constant
    var dx=cp*sa, dy=-sp, dz=-cp*ca;
    // origin coefficients (object space) from world (wx,wy,3)
    var z0=3;
    var scale=res*0.5/1.32, cx=res/2, cy=res/2;

    var base=metal.base, spec=metal.spec, shin=metal.shin, amb=metal.amb;
    var bR=base[0],bG=base[1],bB=base[2], sR=spec[0],sG=spec[1],sB=spec[2];

    var i,j;
    for(j=0;j<res;j++){
      var wy=-((j+0.5-cy)/scale);
      for(i=0;i<res;i++){
        var wx=(i+0.5-cx)/scale;
        var ox=m00*wx + m10*wy - m20*z0*-1*0; // placeholder, compute below properly
        // object origin = M^T * (wx,wy,z0)  (M orthonormal -> inverse is transpose)
        ox = m00*wx + m10*wy + m20*z0;
        var oy = m01*wx + m11*wy + m21*z0;
        var oz = m02*wx + m12*wy + m22*z0;

        var bestS=1e9, hitType=-1, hu=0, hv=0, face=1;

        // caps
        if(Math.abs(dz)>1e-7){
          // +H
          var s=(H-oz)/dz;
          if(s>1e-4 && s<bestS){
            var x=ox+s*dx, y=oy+s*dy;
            if(x*x+y*y<=R*R){bestS=s;hitType=0;hu=x;hv=y;face=1;}
          }
          // -H
          s=(-H-oz)/dz;
          if(s>1e-4 && s<bestS){
            var x2=ox+s*dx, y2=oy+s*dy;
            if(x2*x2+y2*y2<=R*R){bestS=s;hitType=0;hu=x2;hv=y2;face=-1;}
          }
        }
        // side
        var a=dx*dx+dy*dy;
        if(a>1e-9){
          var b=2*(ox*dx+oy*dy), cc=ox*ox+oy*oy-R*R;
          var disc=b*b-4*a*cc;
          if(disc>0){
            var sq=Math.sqrt(disc);
            var s1=(-b-sq)/(2*a), s2=(-b+sq)/(2*a);
            if(s1>1e-4 && s1<bestS){
              var z1=oz+s1*dz;
              if(z1>=-H&&z1<=H){bestS=s1;hitType=1;hu=ox+s1*dx;hv=oy+s1*dy;face=0;}
            }
            if(s2>1e-4 && s2<bestS){
              var z2=oz+s2*dz;
              if(z2>=-H&&z2<=H){bestS=s2;hitType=1;hu=ox+s2*dx;hv=oy+s2*dy;face=0;}
            }
          }
        }

        var di=(j*res+i)*4;

        if(hitType<0){
          // simple dark backdrop with faint center glow
          var ddx=(i-cx)/(res*0.5), ddy=(j-cy)/(res*0.5);
          var gl=Math.exp(-(ddx*ddx+ddy*ddy)*2.0);
          data[di]  =(0.045+0.05*gl)*255;
          data[di+1]=(0.050+0.05*gl)*255;
          data[di+2]=(0.072+0.075*gl)*255;
          data[di+3]=255;
          continue;
        }

        var nx,ny,nz, af=1.0;

        if(hitType===0){
          var u=hu/R, v=hv/R;
          if(face>0){
            texAt(texFront,u,v,tmp);
            nx=DOME*u; ny=DOME*v; nz=1;
            nx+=BUMP*tmp[1]; ny-=BUMP*tmp[2];
          } else {
            texAt(texBack,-u,v,tmp);
            nx=DOME*u; ny=DOME*v; nz=-1;
            nx-=BUMP*tmp[1]; ny-=BUMP*tmp[2];
          }
          af=0.80+0.42*(tmp[0]-0.5);
        } else {
          var pcx=hu/R, pcy=hv/R;
          var th=Math.atan2(pcy,pcx);
          nx=pcx; ny=pcy; nz=0;
          var amp=REEDAMP*Math.cos(th*NR);
          nx+=amp*(-pcy); ny+=amp*(pcx);
          af=0.86;
        }

        var nlen=Math.sqrt(nx*nx+ny*ny+nz*nz)||1;
        nx/=nlen; ny/=nlen; nz/=nlen;

        // to world
        var Nx=m00*nx+m01*ny+m02*nz;
        var Ny=m10*nx+m11*ny+m12*nz;
        var Nz=m20*nx+m21*ny+m22*nz;

        var ndl=Nx*L[0]+Ny*L[1]+Nz*L[2]; if(ndl<0)ndl=0;
        var ndh=Nx*Hx+Ny*Hy+Nz*Hz; if(ndh<0)ndh=0;
        var sp2=Math.pow(ndh,shin);
        var ndv=Nz; if(ndv<0)ndv=0;
        var rim=Math.pow(1-ndv,3);

        var r=(bR*(amb+0.95*ndl))*af + sR*sp2*1.35 + sR*rim*0.14;
        var g2=(bG*(amb+0.95*ndl))*af + sG*sp2*1.35 + sG*rim*0.16;
        var b2=(bB*(amb+0.95*ndl))*af + sB*sp2*1.35 + sB*rim*0.20;

        data[di]  = r>1?255:r*255;
        data[di+1]= g2>1?255:g2*255;
        data[di+2]= b2>1?255:b2*255;
        data[di+3]= 255;
      }
    }
  }

  /* ---------- HERO ---------- */
